# Build the assembled grid from the test pieces and their marker-matched translations.
H=W=26
pieces = {
    '6': ([(2,12),(3,12),(3,13),(3,14),(3,15),(4,12),(5,12),(6,12),(6,13),(6,14),(6,15),(7,12)], [(2,11),(3,16),(6,16),(7,11)], (13,-9), 6),
    '8': ([(r,4) for r in range(8,14)], [(8,5),(13,5)], (7,-3), 8),
    '4': ([(r,c) for r in range(12,17) for c in range(11,15)], [(11,14),(15,10),(16,15),(17,11)], (0,0), 4),
    '5': ([(19,2),(19,3),(20,2),(21,2),(22,2),(22,5),(23,2),(23,5),(24,2),(24,3),(24,4),(24,5)], [(19,4),(20,1),(21,5),(23,1)], (-4,6), 5),
    '9a': ([(3,c) for c in range(21,25)]+[(r,24) for r in range(4,9)]+[(9,23),(9,24)], [(2,24),(3,25),(4,21),(9,22)], (7,-7), 9),
    '9b': ([(13,22),(13,23),(14,22),(15,22),(15,23)], [(13,24),(15,24)], (-7,-8), 9),
    '7': ([(18,c) for c in range(16,20)]+[(19,16),(19,19),(20,16),(20,19),(21,19),(22,18),(22,19)], [(18,15),(20,15),(21,16),(22,17)], (-12,1), 7),
}
grid=[[0]*W for _ in range(H)]
coll=[]
for name,(cells,dots,(dr,dc),color) in pieces.items():
    for r,c in cells:
        rr,cc=r+dr,c+dc
        if not(0<=rr<H and 0<=cc<W): print('OOB cell',name,rr,cc)
        if grid[rr][cc] not in (0,color): coll.append((rr,cc,grid[rr][cc],color,'cell',name))
        grid[rr][cc]=color
for name,(cells,dots,(dr,dc),color) in pieces.items():
    for r,c in dots:
        rr,cc=r+dr,c+dc
        if not(0<=rr<H and 0<=cc<W): print('OOB dot',name,rr,cc)
        if grid[rr][cc] not in (0,2): coll.append((rr,cc,grid[rr][cc],2,'dot',name))
        grid[rr][cc]=2
print('collisions',coll)
print('nonzero rows:')
for i,row in enumerate(grid):
    if any(row): print(i, row)
print('json=',json.dumps(grid,separators=(',',':')))
